package com.villofarm.config;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import org.springframework.web.server.ResponseStatusException;import java.util.Map;@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(ResponseStatusException.class)ResponseEntity<Map<String,String>> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("message",e.getReason()==null?"Request failed":e.getReason()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<Map<String,String>> validation(MethodArgumentNotValidException e){var field=e.getBindingResult().getFieldErrors().stream().findFirst();return ResponseEntity.badRequest().body(Map.of("message",field.map(f->f.getField()+" "+f.getDefaultMessage()).orElse("Invalid request")));}}
